{
  "application": "ppt-generation",
  "case_id": "case-httparchive-state-of-web",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 8,
    "audience": "web performance engineers and front-end architects evaluating infrastructure trends",
    "tone": "data-forward, analytical, technical"
  },
  "brief": {
    "title": "State of the Web 2020–2025: HTTP Archive Trends in Page Weight, Protocols, and Security",
    "one_liner": "A data-driven overview of how web pages have evolved in size, request patterns, protocol adoption, and security practices over the past five years based on HTTP Archive crawl data.",
    "goal": "Equip web performance professionals with a clear understanding of macro-level trends in page weight, HTTPS adoption, HTTP/2 and HTTP/3 usage, TCP connection counts, and font-display best practices so they can benchmark their own sites and prioritize optimization efforts."
  },
  "slides": [
    {
      "id": "title-slide",
      "title": "State of the Web 2020–2025: Tracking Page Weight, Protocols & Security at Scale",
      "objective": "Cover slide with the deck title, subtitle referencing HTTP Archive as the data source, and the time range Jan 2020 – Mar 2026."
    },
    {
      "id": "sample-size-growth",
      "title": "Crawl Sample Size Tripled: From ~5M to 16M Desktop URLs Since 2020",
      "objective": "Show the dramatic growth in HTTP Archive sample size for both desktop and mobile using a dual-line time-series chart (reference figure_1). Emphasize the sharp jump around mid-2022 and the current plateau near 16M desktop / 12.5M mobile URLs."
    },
    {
      "id": "page-weight-trends",
      "title": "Median Page Weight Climbs Steadily to ~2,000 KB on Desktop",
      "objective": "Present the Total Kilobytes time-series (reference figure_2) showing desktop median rising from ~1,600 KB to ~2,000 KB and mobile tracking slightly below. Include the interquartile shaded bands to illustrate variance. Use a line chart with confidence bands."
    },
    {
      "id": "requests-and-connections",
      "title": "76 Requests per Desktop Page While TCP Connections Drop to 12",
      "objective": "Combine two metrics on one slide: total requests per page (76 desktop / 71 mobile, both up ~3%) and TCP connections per page declining from ~15 to ~12 (reference figure_3). Use a split layout with a small bar/stat card for requests and a declining line chart for TCP connections, noting the efficiency gains from multiplexing."
    },
    {
      "id": "https-near-universal",
      "title": "HTTPS Requests Reach 99%: Encryption Is Now the Default",
      "objective": "Highlight that 99.2% of desktop and 99.1% of mobile requests use HTTPS, up ~19–20% from 2020. Use a single large stat callout plus a small time-series showing the climb from ~80% to 99%. Emphasize that plaintext HTTP is effectively gone."
    },
    {
      "id": "http2-http3-adoption",
      "title": "HTTP/2 Holds at ~58% While HTTP/3 Support Surges to 40%",
      "objective": "Show protocol adoption side by side. HTTP/2 is relatively flat (~58–59%), while HTTP/3 support has exploded from near-zero to ~39–40%. Use a stacked or grouped bar chart for the latest snapshot and a small inset time-series for HTTP/3's rapid rise. Note the measurement caveat about fresh Chrome instances."
    },
    {
      "id": "font-display-adoption",
      "title": "Font-Display Usage Reaches 42% on Mobile, Up 61% Since 2020",
      "objective": "Present the font-display CSS property adoption trend. Desktop at 40.1%, mobile at 42.5%. Use a line chart or bar comparison showing the growth trajectory. Explain the FOIT avoidance benefit briefly."
    },
    {
      "id": "key-takeaways",
      "title": "Key Takeaways: Bigger Pages, Smarter Protocols, Stronger Security",
      "objective": "Summary slide with 4–5 bullet-point takeaways: (1) Page weight continues to grow but at a moderate pace; (2) HTTPS is effectively universal; (3) HTTP/3 support is the fastest-growing metric; (4) TCP connections are declining thanks to multiplexing; (5) Font-display adoption still has room to grow. End with a call to action to benchmark against these baselines."
    }
  ]
}

