    <script>
        /* === SLIDE PRESENTATION CONTROLLER === */
        class SlidePresentation {
            constructor() {
                this.slides = document.querySelectorAll('.slide');
                this.currentSlide = 0;
                this.isScrolling = false;
                this.setupIntersectionObserver();
                this.setupKeyboardNav();
                this.setupTouchNav();
                this.setupProgressBar();
                this.setupNavDots();
                this.setupWheelNav();
            }

            setupIntersectionObserver() {
                const observer = new IntersectionObserver(
                    (entries) => {
                        entries.forEach(entry => {
                            if (entry.isIntersecting) {
                                entry.target.classList.add('visible');
                                const idx = Array.from(this.slides).indexOf(entry.target);
                                if (idx !== -1) {
                                    this.currentSlide = idx;
                                    this.updateProgressBar();
                                    this.updateNavDots();
                                }
                            }
                        });
                    },
                    { threshold: 0.5 }
                );
                this.slides.forEach(slide => observer.observe(slide));
            }

            setupKeyboardNav() {
                document.addEventListener('keydown', (e) => {
                    if (['ArrowDown', 'ArrowRight', 'Space', 'PageDown'].includes(e.code)) {
                        e.preventDefault();
                        this.goToSlide(this.currentSlide + 1);
                    } else if (['ArrowUp', 'ArrowLeft', 'PageUp'].includes(e.code)) {
                        e.preventDefault();
                        this.goToSlide(this.currentSlide - 1);
                    } else if (e.code === 'Home') {
                        e.preventDefault();
                        this.goToSlide(0);
                    } else if (e.code === 'End') {
                        e.preventDefault();
                        this.goToSlide(this.slides.length - 1);
                    }
                });
            }

            setupTouchNav() {
                let startY = 0;
                document.addEventListener('touchstart', (e) => { startY = e.touches[0].clientY; });
                document.addEventListener('touchend', (e) => {
                    const diff = startY - e.changedTouches[0].clientY;
                    if (Math.abs(diff) > 50) {
                        this.goToSlide(this.currentSlide + (diff > 0 ? 1 : -1));
                    }
                });
            }

            setupWheelNav() {
                let wheelTimeout;
                document.addEventListener('wheel', (e) => {
                    if (this.isScrolling) return;
                    clearTimeout(wheelTimeout);
                    wheelTimeout = setTimeout(() => {
                        if (Math.abs(e.deltaY) > 30) {
                            this.isScrolling = true;
                            this.goToSlide(this.currentSlide + (e.deltaY > 0 ? 1 : -1));
                            setTimeout(() => { this.isScrolling = false; }, 800);
                        }
                    }, 50);
                }, { passive: true });
            }

            goToSlide(index) {
                const target = Math.max(0, Math.min(index, this.slides.length - 1));
                this.slides[target].scrollIntoView({ behavior: 'smooth' });
                this.currentSlide = target;
                this.updateProgressBar();
                this.updateNavDots();
            }

            setupProgressBar() {
                this.progressBar = document.getElementById('progressBar');
                this.updateProgressBar();
            }

            updateProgressBar() {
                const pct = ((this.currentSlide + 1) / this.slides.length) * 100;
                this.progressBar.style.width = pct + '%';
            }

            setupNavDots() {
                const nav = document.getElementById('navDots');
                this.slides.forEach((_, i) => {
                    const dot = document.createElement('button');
                    dot.className = 'nav-dot' + (i === 0 ? ' active' : '');
                    dot.addEventListener('click', () => this.goToSlide(i));
                    dot.setAttribute('aria-label', 'Go to slide ' + (i + 1));
