            }

            updateNavDots() {
                this.dots.forEach((dot, i) => {
                    dot.classList.toggle('active', i === this.currentSlide);
                });
            }
        }

        /* === CANVAS CHART DRAWING === */
        function drawChart(canvasId, config) {
            const canvas = document.getElementById(canvasId);
            if (!canvas) return;
            const ctx = canvas.getContext('2d');
            const dpr = window.devicePixelRatio || 1;
            const rect = canvas.getBoundingClientRect();
            canvas.width = rect.width * dpr;
            canvas.height = rect.height * dpr;
            ctx.scale(dpr, dpr);

            const w = rect.width;
            const h = rect.height;
            const pad = { top: 30, right: 20, bottom: 35, left: 55 };
            const plotW = w - pad.left - pad.right;
            const plotH = h - pad.top - pad.bottom;

            const { datasets, labels, yMin, yMax, yStep, yLabel, bandData } = config;

            ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--text-muted').trim();
            ctx.font = `${Math.max(9, w * 0.018)}px JetBrains Mono, monospace`;
            ctx.textAlign = 'right';
            ctx.textBaseline = 'middle';

            for (let v = yMin; v <= yMax; v += yStep) {
                const y = pad.top + plotH - ((v - yMin) / (yMax - yMin)) * plotH;
                ctx.fillText(yLabel ? yLabel(v) : v, pad.left - 8, y);

                ctx.strokeStyle = 'rgba(122, 139, 170, 0.12)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(pad.left, y);
                ctx.lineTo(pad.left + plotW, y);
                ctx.stroke();
            }

            ctx.textAlign = 'center';
            ctx.textBaseline = 'top';
            const labelStep = Math.max(1, Math.floor(labels.length / 6));
            labels.forEach((label, i) => {
                if (i % labelStep === 0 || i === labels.length - 1) {
                    const x = pad.left + (i / (labels.length - 1)) * plotW;
                    ctx.fillText(label, x, pad.top + plotH + 10);
                }
            });

            if (bandData) {
                ctx.fillStyle = bandData.color;
                ctx.beginPath();
                bandData.upper.forEach((v, i) => {
                    const x = pad.left + (i / (bandData.upper.length - 1)) * plotW;
                    const y = pad.top + plotH - ((v - yMin) / (yMax - yMin)) * plotH;
                    i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
                });
                for (let i = bandData.lower.length - 1; i >= 0; i--) {
                    const x = pad.left + (i / (bandData.lower.length - 1)) * plotW;
                    const y = pad.top + plotH - ((bandData.lower[i] - yMin) / (yMax - yMin)) * plotH;
                    ctx.lineTo(x, y);
                }
                ctx.closePath();
                ctx.fill();
            }

            datasets.forEach(ds => {
                ctx.strokeStyle = ds.color;
                ctx.lineWidth = ds.lineWidth || 2.5;
                ctx.lineJoin = 'round';
                ctx.lineCap = 'round';

                if (ds.dashed) ctx.setLineDash([6, 4]);
                else ctx.setLineDash([]);

                ctx.beginPath();
                ds.data.forEach((v, i) => {
                    const x = pad.left + (i / (ds.data.length - 1)) * plotW;
                    const y = pad.top + plotH - ((v - yMin) / (yMax - yMin)) * plotH;
                    i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
                });
                ctx.stroke();

                const lastVal = ds.data[ds.data.length - 1];
                const lastX = pad.left + plotW;
                const lastY = pad.top + plotH - ((lastVal - yMin) / (yMax - yMin)) * plotH;
                ctx.fillStyle = ds.color;
                ctx.beginPath();
                ctx.arc(lastX, lastY, 4, 0, Math.PI * 2);
                ctx.fill();
            });

            ctx.setLineDash([]);
        }

        /* === INITIALIZE CHARTS ON LOAD === */
        function initAllCharts() {
            const timeLabels6 = ['2020', '2021', '2022', 'H2 2022', '2023', '2024', '2025'];

            drawChart('sampleSizeChart', {
                labels: timeLabels6,
                datasets: [
                    { data: [5, 5.2, 5.5, 14.5, 15.5, 16, 16], color: '#00e5cc', lineWidth: 3 },
                    { data: [3.5, 3.8, 4, 9.5, 11, 12, 12.5], color: '#ff8b3e', lineWidth: 3 }
                ],
                yMin: 0, yMax: 18, yStep: 3,
                yLabel: v => v + 'M'
            });

            drawChart('pageWeightChart', {
                labels: timeLabels6,
                datasets: [
                    { data: [1600, 1650, 1720, 1780, 1850, 1930, 2000], color: '#00e5cc', lineWidth: 3 },
                    { data: [1500, 1550, 1600, 1660, 1730, 1810, 1900], color: '#ff8b3e', lineWidth: 3 }
                ],
                bandData: {
                    upper: [2800, 2950, 3100, 3300, 3600, 3850, 4100],
                    lower: [800, 820, 850, 870, 900, 920, 950],
                    color: 'rgba(0, 229, 204, 0.06)'
                },
                yMin: 0, yMax: 4500, yStep: 500,
                yLabel: v => (v / 1000).toFixed(1) + 'k'
            });

            drawChart('tcpChart', {
                labels: timeLabels6,
                datasets: [
                    { data: [15, 14.5, 14, 13.5, 13, 12.5, 12], color: '#00e5cc', lineWidth: 3 },
                    { data: [15, 14, 13.5, 13, 12.5, 11.5, 11], color: '#ff8b3e', lineWidth: 3 }
                ],
                yMin: 8, yMax: 17, yStep: 1,
                yLabel: v => v
            });

            const httpsLabels = ['2020', '2021', '2022', '2023', '2024', '2025'];
            drawChart('httpsChart', {
                labels: httpsLabels,
                datasets: [
                    { data: [80, 85, 90, 95, 98, 99.2], color: '#39d353', lineWidth: 3 }
                ],
                yMin: 75, yMax: 100, yStep: 5,
                yLabel: v => v + '%'
            });

            const fontLabels = ['2020', '2021', '2022', '2023', '2024', '2025'];
            drawChart('fontDisplayChart', {
                labels: fontLabels,
                datasets: [
                    { data: [35, 35.5, 36, 37, 38.5, 40.1], color: '#4488ff', lineWidth: 2.5 },
                    { data: [26.4, 29, 32, 35, 38, 42.5], color: '#ff8b3e', lineWidth: 2.5 }
                ],
                yMin: 20, yMax: 50, yStep: 5,
                yLabel: v => v + '%'
            });
        }

        document.addEventListener('DOMContentLoaded', () => {
            new SlidePresentation();
            initAllCharts();

            window.addEventListener('resize', () => {
                clearTimeout(window._resizeTimer);
                window._resizeTimer = setTimeout(initAllCharts, 200);
            });
        });
    </script>
</body>
