#!/usr/bin/env python3
"""Convert HTML presentation to PPTX with reliable per-slide screenshots.

Uses a custom Playwright script that scrolls directly to each .slide element
by index, avoiding timing issues with keyboard-based navigation.
"""

import argparse
import json
import os
import http.server
import subprocess
import sys
import tempfile
import threading
from pathlib import Path

from PIL import Image
from pptx import Presentation
from pptx.util import Emu


def _make_screenshot_script(url: str, out_dir: str, width: int, height: int) -> str:
    return f"""\
const {{ chromium }} = require('playwright');

(async () => {{
    const browser = await chromium.launch({{ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH || undefined }});
    const page = await browser.newPage();
    await page.setViewportSize({{ width: {width}, height: {height} }});
    await page.goto('{url}', {{ waitUntil: 'networkidle' }});

    // Wait for fonts and initial render
    await page.waitForTimeout(1500);

    // Count slides
    const slideCount = await page.$$eval('.slide', els => els.length);
    console.error('Found ' + slideCount + ' slides');

    if (slideCount === 0) {{
        console.log(JSON.stringify({{ captured: 0 }}));
        await browser.close();
        return;
    }}

    let captured = 0;

    for (let i = 0; i < slideCount; i++) {{
        // Scroll directly to the slide element and make it visible
        await page.evaluate((idx) => {{
            const slides = document.querySelectorAll('.slide');
            if (slides[idx]) {{
                // Disable smooth scrolling for instant jump
                document.documentElement.style.scrollBehavior = 'auto';
                slides[idx].scrollIntoView({{ behavior: 'instant', block: 'start' }});
                // Force visible class for animations
                slides[idx].classList.add('visible');
            }}
        }}, i);

        // Wait for render + any entrance animations
        await page.waitForTimeout(800);

        const idx = String(i + 1).padStart(3, '0');
        const path = `{out_dir}/slide_${{idx}}.png`;
        await page.screenshot({{ path }});
        captured++;
        console.error('Captured slide ' + (i + 1));
    }}

    console.log(JSON.stringify({{ captured }}));
    await browser.close();
}})();
"""


def _start_http_server(directory: Path, port: int = 0):
    handler = http.server.SimpleHTTPRequestHandler
    server = http.server.HTTPServer(
        ("127.0.0.1", port),
        lambda *a, **kw: handler(*a, directory=str(directory), **kw)
    )
    actual_port = server.server_address[1]
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()
    return server, actual_port


def screenshot_slides(html_path: Path, out_dir: Path, width: int, height: int) -> list:
    serve_dir = html_path.resolve().parent
    server, port = _start_http_server(serve_dir)
    url = f"http://127.0.0.1:{port}/{html_path.resolve().name}"

    try:
        script = _make_screenshot_script(url, str(out_dir), width, height)
        script_file = out_dir / "_capture.cjs"
        script_file.write_text(script)

        env = os.environ.copy()
        env.setdefault("NODE_PATH", "/usr/local/lib/node_modules:/app/node_modules")
        env.setdefault("PLAYWRIGHT_BROWSERS_PATH", "/ms-playwright")
        env.setdefault("PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD", "1")

        result = subprocess.run(
            ["node", str(script_file)],
            capture_output=True,
            text=True,
            timeout=180,
            env=env,
        )
        print(result.stderr, file=sys.stderr)
        if result.returncode != 0:
            raise RuntimeError(f"Screenshot script failed (exit {result.returncode})")
    finally:
        server.shutdown()

    pngs = sorted(out_dir.glob("slide_*.png"))
    if not pngs:
        raise RuntimeError("No slide screenshots produced")
    return pngs


def assemble_pptx(slide_images: list, output_path: Path) -> None:
    prs = Presentation()
    prs.slide_width = Emu(12192000)
    prs.slide_height = Emu(6858000)
    blank_layout = prs.slide_layouts[6]

    for img_path in slide_images:
        slide = prs.slides.add_slide(blank_layout)
        slide.shapes.add_picture(
            str(img_path),
            left=Emu(0), top=Emu(0),
            width=prs.slide_width, height=prs.slide_height,
        )

    prs.save(str(output_path))


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("input_html")
    parser.add_argument("output_pptx")
    parser.add_argument("--width", type=int, default=1920)
